// HostServer is the server API for Host service.
// All implementations must embed UnimplementedHostServer
// for forward compatibility.
//
// Host service: implemented by tau (the host), called by plugins.
type HostServer interface {
	// UI prompts (headless via runtime's UI interface).
	UIConfirm(context.Context, *UIConfirmRequest) (*UIConfirmResponse, error)
	UISelect(context.Context, *UISelectRequest) (*UISelectResponse, error)
	UIInput(context.Context, *UIInputRequest) (*UIInputResponse, error)
	UINotify(context.Context, *UINotifyRequest) (*UINotifyResponse, error)
	UISetStatus(context.Context, *UISetStatusRequest) (*UISetStatusResponse, error)
	UISetWidget(context.Context, *UISetWidgetRequest) (*UISetWidgetResponse, error)
	UISetTitle(context.Context, *UISetTitleRequest) (*UISetTitleResponse, error)
	UISetEditorText(context.Context, *UISetEditorTextRequest) (*UISetEditorTextResponse, error)
	UISetToolsExpanded(context.Context, *UISetToolsExpandedRequest) (*UISetToolsExpandedResponse, error)
	// Logging.
	Log(context.Context, *LogRequest) (*LogResponse, error)
	// Configuration access.
	GetConfig(context.Context, *GetConfigRequest) (*GetConfigResponse, error)
	// Tool progress streaming.
	ToolProgress(context.Context, *ToolProgressEvent) (*ToolProgressResponse, error)
	// Per-plugin state (namespaced, persisted under ~/.tau/agent/plugin-state/<name>/).
	StateGet(context.Context, *StateGetRequest) (*StateGetResponse, error)
	StateSet(context.Context, *StateSetRequest) (*StateSetResponse, error)
	StateAppend(context.Context, *StateAppendRequest) (*StateAppendResponse, error)
	StateDelete(context.Context, *StateDeleteRequest) (*StateDeleteResponse, error)
	// Session-scoped operations (active session only).
	SessionAppend(context.Context, *SessionAppendRequest) (*SessionAppendResponse, error)
	SessionScan(context.Context, *SessionScanRequest) (*SessionScanResponse, error)
	SessionSetLabel(context.Context, *SessionSetLabelRequest) (*SessionSetLabelResponse, error)
	SessionGetLabel(context.Context, *SessionGetLabelRequest) (*SessionGetLabelResponse, error)
	// Send a user message to the active session.
	// deliver_as: "" → normal send (queued as next turn),
	//
	//	"steer" → injected mid-stream (RPC steer),
	//	"followUp" → queued after the current turn finishes.
	//
	// Mirrors pi's pi.sendUserMessage semantics.
	SessionSendUserMessage(context.Context, *SessionSendUserMessageRequest) (*SessionSendUserMessageResponse, error)
	mustEmbedUnimplementedHostServer()
}

